<PageTitle>Dashboard – @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Site</h5>
        <p class="card-text fs-4">@WarehouseState.CurrentWarehouseName</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            <AlertBadge />
        </p>
        <p class="text-muted small">Refreshes every 10 seconds while this page is open.</p>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
        AlertService.OnAlertCountChanged += OnStateChanged;
        AlertService.StartPolling();
    }

    private void OnStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
        AlertService.OnAlertCountChanged -= OnStateChanged;
        AlertService.StopPolling();
    }
}

